import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"はじめに","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/getting-started.md","filePath":"ja-JP/user-guide/getting-started.md","lastUpdated":1787551561000}'),d={name:"ja-JP/user-guide/getting-started.md"};function n(s,e,i,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h1><h2 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h2><p>ホームページの<a href="./../">ダウンロードボタン</a>から最新リリースを入手してください。各リリースでは 2 種類の形式が公開されています:</p><ul><li><strong>インストーラー</strong> (<code>Lertaro-Setup.exe</code>) — 推奨。バックグラウンドのインデックスサービスを登録し、Lertaro を Windows と共に起動できるようにします。</li><li><strong>ポータブル版</strong> (<code>Lertaro-Portable.zip</code>) — 解凍して実行するだけで、インストールは不要です。バックグラウンドサービスは後から <strong>設定 → サービスの状態</strong> でインストールすることもできます。お使いのマシンに Lertaro が必要とする .NET Desktop Runtime がまだ入っていない場合は、同梱されている <code>install-dotnet-runtime.bat</code> を一度実行してください — インストーラー版ではこの手順は自動的に行われますが、ポータブル版では自動化されていません。ポータブル版の利用を終える際には、後片付けをしてくれるアンインストーラーがありません。フォルダーを削除する前に、同梱の <code>portable-cleanup.bat</code> を実行してください。サービスがインストールされている場合は Lertaro のバックグラウンドサービスを停止・削除し、現在のユーザーに登録された <code>lertaro://</code> URI プロトコルと「Windows と共に起動する」項目も削除します。サービスの削除では管理者権限の確認が表示される場合がありますが、それ以外の処理は現在のユーザーに対して行われます。</li></ul><p>このいずれもが <strong>x64</strong> 版と <strong>ARM64</strong> 版として公開されています。上記の名前は x64 版で、最近の PC であればどれでも動作します — Windows on ARM でもエミュレーションで動作します。ARM のマシンでは、ネイティブに動作する <code>Lertaro-Setup-arm64.exe</code> または <code>Lertaro-Portable-arm64.zip</code> をお使いください。自動更新はインストールした際のアーキテクチャを維持するため、もう一方に移行するには自分でダウンロードする必要があります。</p><h2 id="ポータブル-データ" tabindex="-1">ポータブル データ <a class="header-anchor" href="#ポータブル-データ" aria-label="Permalink to &quot;ポータブル データ&quot;">​</a></h2><p>ポータブル版は、アプリケーションの横にある <code>Data\\Machine</code> にマシン データを、<code>Data\\Users\\&lt;SID hash&gt;</code> に各ユーザーのプライベート データを保存します。<code>Data</code> フォルダーがまだ作成されていない場合は、互換性のため既存の <code>%ProgramData%\\Lertaro</code> と <code>%LocalAppData%\\Lertaro</code> のデータを再利用します。<code>Data</code> を作成すると、このポータブル版が自身のデータを優先して自己完結したコピーになります。</p><p>初回起動時、Lertaro はファイルのインデックス化を担う Windows サービス (<code>Lertaro.Service</code>) をインストールして起動します。この分離構成は意図的なものです — 理由が気になる方は<a href="./../dev-guide/architecture.html">アーキテクチャ</a>を参照してください — が、ユーザーとして知っておく必要があるのは、<strong>設定 → サービスの状態</strong> でサービスがインストール済みかどうか、実行中かどうかを確認でき、インストールされていなければそこからインストールできる、ということだけです。</p><h2 id="_3-つのウィンドウ" tabindex="-1">3 つのウィンドウ <a class="header-anchor" href="#_3-つのウィンドウ" aria-label="Permalink to &quot;3 つのウィンドウ&quot;">​</a></h2><p>Lertaro には検索ウィンドウが 1 つだけではなく、使い方に応じて適応する複数のウィンドウがあります:</p><ul><li><strong>メインウィンドウ</strong> — タスクバーやスタートメニューのショートカットから開くフルサイズのウィンドウで、最も大きな検索結果リストと、ウィンドウ内のアクションパネルを備えています。</li><li><strong>クイックウィンドウ</strong> — グローバルなトグルホットキー (既定では <code>Ctrl</code> のダブルタップ) で呼び出す、コンパクトで常に最前面に表示されるポップアップです。「ホットキーを押す → 入力する → Enter」という一連の動作を素早く行えるように作られています。</li><li><strong>インラインウィンドウ</strong> — 対応するネイティブのファイルダイアログやエクスプローラーのウィンドウに Lertaro の検索バーを直接埋め込みます。すでに開いているダイアログから離れることなく検索できます。</li></ul><p>3 つのウィンドウはいずれも同じ検索エンジン、ホットキーシステム、アクションメニューを共有しています。違いは、どこに、どのように表示されるかだけです。</p><h2 id="基本的な検索" tabindex="-1">基本的な検索 <a class="header-anchor" href="#基本的な検索" aria-label="Permalink to &quot;基本的な検索&quot;">​</a></h2><p>最近使ったファイル・お気に入り・履歴は、何も入力せずに取り出せます — これらは<a href="./settings/quick-panel.html">クイックパネル</a>のタブで、このパネルは検索ウィンドウの中ではなく、前面にあるウィンドウに重ねて開きます。</p><p>そのまま入力を始めてください。検索結果は入力するたびに更新され、関連性に基づいて並び替えられます (マッチングとランキングの仕組みについては<a href="./search-syntax.html">検索構文</a>を参照)。選択を移動するには<a href="./hotkeys.html">設定可能な次/前のアイテム用ホットキー</a> (既定では矢印キー) を使用し、Enter でハイライトされている検索結果を開きます。</p><p>次は <a href="./search-syntax.html">検索構文</a> で、クエリボックスを最大限に活用する方法を確認しましょう。</p>',16)])])}const u=a(d,[["render",n]]);export{g as __pageData,u as default};
